PLURALS = {"notif_running": ({"zero":"لا تنزيلات","one":"يجري تنزيل ملف واحد","two":"يجري تنزيل ملفين","few":"يجري تنزيل %d ملفات","many":"يجري تنزيل %d ملفاً","other":"يجري تنزيل %d ملف"},
                             {"one":"Downloading %d file","other":"Downloading %d files"})}

def esc(s):
    s = s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("'", "\\'").replace('"','\\"')
    if s.startswith("@") or s.startswith("?"): s = "\\" + s
    return s

import sys, re
base = sys.argv[1]
for idx, folder in ((0,"values"),(1,"values-en")):
    out = ['<?xml version="1.0" encoding="utf-8"?>', '<resources>']
    for k,v in S.items():
        txt = v[idx]
        fmt = ' formatted="false"' if ('%' in txt and not re.search(r'%\d\$', txt)) else ''
        out.append(f'    <string name="{k}"{fmt}>{esc(txt)}</string>')
    for k,v in PLURALS.items():
        out.append(f'    <plurals name="{k}">')
        for q,t in v[idx].items(): out.append(f'        <item quantity="{q}">{esc(t)}</item>')
        out.append('    </plurals>')
    out.append('</resources>')
    open(f"{base}/{folder}/strings.xml","w").write("\n".join(out)+"\n")
print(len(S))
